{[Fact] public void ValidReplayCaptureRollbackAndJsonRemainTypedOwnerPaths(){string r=Read("HybridCPU_ISE","CloseToHSL","Core","Pipeline","MicroOps","Replay","ReplayToken.cs");string v=Read("HybridCPU_ISE","NonRTL","Processor","Verification","Processor.Verification.cs");Assert.Contains("public ReplayToken BindMainMemory",r,StringComparison.Ordinal);Assert.Contains("CaptureMemoryState",r,StringComparison.Ordinal);Assert.Contains("public void Rollback",r,StringComparison.Ordinal);Assert.Contains("public static ReplayToken FromJson",r,StringComparison.Ordinal);Assert.Contains("CreateReplayTokenFromLiveState",v,StringComparison.Ordinal);Assert.Contains("ApplyReplayTokenToLiveVerificationCore",v,StringComparison.Ordinal);}private static string Read(params string[] p)=>File.ReadAllText(Path.Combine(new[]{Root()}.Concat(p).ToArray()));private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"HybridCPU_ISE")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
